161	    public String getCustomerCode() {
162	        return this.customerCode;
163	    }
164	
165	    public void setCustomerCode(String customerCode) {
166	        this.customerCode = customerCode;
167	    }
168	
169	    public String getHouseholdId() {
170	        return this.householdId;
171	    }
172	
173	    public void setHouseholdId(String householdId) {
174	        this.householdId = householdId;
175	    }
176	
177	    public Integer getNamesakeCount() {
178	        return this.namesakeCount;
179	    }
180	
181	    public void setNamesakeCount(Integer namesakeCount) {
182	        this.namesakeCount = namesakeCount;
183	    }
