209	    /**
210	     * The owner's membership points, accumulated from four factors: start at 0, add 2
211	     * when an email is present, add 1 when {@code namesakeCount} is 0, add 2 for a
212	     * household of 3 or more members, and add 3 when the owner's tenure exceeds 365
213	     * days. The tenure points are the only route to 6 or more: because a newly created
214	     * owner has zero tenure, a new owner scores at most 5 points (2 email + 1 namesake
215	     * + 2 household).
216	     */
217	    @Transient
218	    public int getMembershipPoints() {
219	        int points = 0;
220	        if (this.email != null && !this.email.isBlank()) {
221	            points += 2;
222	        }
223	        if (this.namesakeCount != null && this.namesakeCount == 0) {
224	            points += 1;
225	        }
226	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
227	            points += 2;
228	        }
229	        if (getTenureDays() > 365) {
230	            points += 3;
231	        }
232	        return points;
233	    }
234	
235	    /**
236	     * The owner's numeric membership level, derived from {@link #getMembershipPoints()}:
237	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more. Because a newly
238	     * created owner scores at most 5 points (tenure being the only route to 6), a new
239	     * owner never exceeds level 3.
240	     */
241	    @Transient
242	    public int getMembershipLevel() {
243	        int points = getMembershipPoints();
244	        if (points <= 1) {
245	            return 1;
246	        }
247	        if (points <= 3) {
248	            return 2;
249	        }
250	        if (points <= 5) {
251	            return 3;
252	        }
253	        return 4;
254	    }
255	
256	    /**
257	     * The owner's tenure in whole days: the span from {@code registrationDate} to today.
258	     * Zero when no registration date is set, and zero for an owner registered today, so
259	     * the tenure point of {@link #getMembershipLevel()} is never earned at creation.
260	     */
261	    @Transient
262	    public long getTenureDays() {
263	        if (this.registrationDate == null) {
264	            return 0;
265	        }
266	        return java.time.temporal.ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
267	    }
268	
269	    /**
270	     * The owner's canonical region, preferring the postcode over the city.
271	     *
272	     * <p>The 4-digit postcode range is consulted first (NSW 2000-2099, VIC 3000-3099,
273	     * QLD 4000-4099); only when the postcode is absent or in no known range does this
274	     * fall back to the fixed city-to-region table (Sydney-&gt;NSW, Melbourne-&gt;VIC,
275	     * Brisbane-&gt;QLD). Anything unresolved is {@code "UNKNOWN"}. This single derivation
276	     * backs both the {@code locality} field and the {@code REGION} segment of the
277	     * {@code customerCode}, so the two always agree.
278	     */
279	    @Transient
280	    public String getRegion() {
281	        if (this.postcode != null && this.postcode.matches("[0-9]{4}")) {
282	            int value = Integer.parseInt(this.postcode);
283	            if (value >= 2000 && value <= 2099) {
284	                return "NSW";
285	            }
286	            if (value >= 3000 && value <= 3099) {
287	                return "VIC";
288	            }
289	            if (value >= 4000 && value <= 4099) {
290	                return "QLD";
291	            }
292	        }
293	        if ("Sydney".equals(this.city)) {
294	            return "NSW";
295	        }
296	        if ("Melbourne".equals(this.city)) {
297	            return "VIC";
298	        }
299	        if ("Brisbane".equals(this.city)) {
300	            return "QLD";
301	        }
302	        return "UNKNOWN";
303	    }
304	
305	    /**
306	     * The owner's IANA timezone, derived from {@link #getRegion()} via the fixed
307	     * region-to-timezone table (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne,
308	     * QLD-&gt;Australia/Brisbane). {@code null} when the region is not in the table.
309	     */
310	    @Transient
311	    public String getTimezone() {
312	        switch (getRegion()) {
313	            case "NSW":
314	                return "Australia/Sydney";
315	            case "VIC":
316	                return "Australia/Melbourne";
317	            case "QLD":
318	                return "Australia/Brisbane";
319	            default:
320	                return null;
321	        }
322	    }
323	
324	    /**
325	     * The owner's preferred contact channel: {@code EMAIL} when an email address is
326	     * present, otherwise {@code PHONE}.
327	     */
328	    @Transient
329	    public String getContactPreference() {
330	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
331	    }
332	
333	    /**
334	     * The owner's derived duplicate-detection key: the normalized (E.164) telephone,
335	     * the email (or empty when absent) and the {@code householdId} (or empty when
336	     * absent), joined by {@code '|'}. Two owners are duplicates only when their whole
337	     * identity keys are equal.
338	     */
339	    @Transient
340	    public String getIdentityKey() {
341	        String tel = this.telephone == null ? "" : this.telephone;
342	        String mail = this.email == null ? "" : this.email;
343	        String household = this.householdId == null ? "" : this.householdId;
344	        return tel + "|" + mail + "|" + household;
345	    }
